// 1. Pega os clientes vindos do nó Webhook
// (Ajuste o nome do nó 'Webhook' se você renomeou)
const webhookData = $('Webhook').first().json;
const clientes = webhookData.body?.clientes || webhookData.clientes || [];

// 2. Pega todos os itens lidos do CSV
// (Ajuste 'Extract from File' para o nome exato do seu nó de CSV)
const investimentos = $('Extract from File').all().map(item => item.json);

// 3. Cruza os dados: para cada cliente, acha o investimento compatível
const resultado = clientes.map(cliente => {
  // Procura o produto com o mesmo perfil do cliente
  const produtoIndicado = investimentos.find(inv => 
    inv.perfil?.toLowerCase() === cliente.perfil?.toLowerCase()
  );

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      produto: produtoIndicado ? produtoIndicado.produto : "Nenhum produto encontrado",
      rentabilidade: produtoIndicado ? produtoIndicado.rentabilidade : "N/A",
      minimo: produtoIndicado ? produtoIndicado.minimo : "N/A"
    }
  };
});

return resultado;

